\n// path: test/fitur/event/page/event_page_a_test.dart\nimport 'dart:async';\n\nimport 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'package:flutter_test/flutter_test.dart';\nimport 'package:wifi/fitur/event/model/event_model.dart';\nimport 'package:wifi/fitur/event/page/event_page_a.dart';\n\nvoid main() {\n  group('EventPageA', () {\n    late ProviderContainer container;\n    late StreamController<List<EventModel>> streamController;\n\n    setUp(() {\n      streamController = StreamController<List<EventModel>>();\n      container = ProviderContainer(\n        overrides: [\n          announcementsStreamProvider.overrideWith((ref) => streamController.stream),\n        ],\n      );\n    });\n\n    tearDown(() {\n      streamController.close();\n      container.dispose();\n    });\n\n    Future<void> pumpWidget(WidgetTester tester) async {\n      await tester.pumpWidget(\n        UncontrolledProviderScope(\n          container: container,\n          child: const MaterialApp(home: EventPageA()),\n        ),\n      );\n    }\n\n    testWidgets('01. Menampilkan CircularProgressIndicator saat loading', (tester) async {\n      await pumpWidget(tester);\n      expect(find.byType(CircularProgressIndicator), findsOneWidget);\n    });\n\n    testWidgets('02. Menampilkan pesan error saat terjadi kesalahan', (tester) async {\n      await pumpWidget(tester);\n      streamController.addError(Exception('Gagal memuat data'));\n      await tester.pump();\n      expect(find.text('Gagal memuat pengumuman.'), findsOneWidget);\n    });\n\n    testWidgets('03. Menampilkan pesan saat tidak ada pengumuman', (tester) async {\n      await pumpWidget(tester);\n      streamController.add([]);\n      await tester.pump();\n      expect(find.text('Belum ada pengumuman.'), findsOneWidget);\n    });\n\n    testWidgets('04. Menampilkan daftar pengumuman', (tester) async {\n      final eventList = [\n        EventModel(\n            id: '1',\n            linkGambar: 'img1.png',\n            statusAktif: true,\n            tanggalDibuat: DateTime.now(),\n            tanggalMulai: DateTime.now(),\n            tanggalBerakhir: DateTime.now()),\n        EventModel(\n            id: '2',\n            linkGambar: 'img2.png',\n            statusAktif: false,\n            tanggalDibuat: DateTime.now(),\n            tanggalMulai: DateTime.now(),\n            tanggalBerakhir: DateTime.now()),\n      ];\n\n      await pumpWidget(tester);\n      streamController.add(eventList);\n      await tester.pump();\n\n      expect(find.byType(Card), findsNWidgets(2));\n      expect(find.text('Aktif'), findsOneWidget);\n      expect(find.text('Tidak Aktif'), findsOneWidget);\n    });\n  });\n}\n